"""Checks of Paper F: every number of main.tex that a script of this repository reproduces.

Each entry is a call  C(id, loc, paper, log, pattern, ...)  with
    id       short name
    loc      place in main.tex (section / table / equation / sentence)
    paper    the value as written in the manuscript, as a plain decimal string ('1.3e-7', '0.0489'); the tolerance of 'eq' checks is
             half a unit of its last digit plus half a unit of the last digit printed in the log (rounding only)
    log      id of the regenerated log in verification/logs/ (= a job of verify.py)
    pattern  regular expression (re.M|re.S off) whose group `grp` (default 1) is the number in the log; the `n`-th match is used
    kind     'eq' (default): |computed*scale - paper| <= tol;  'le': computed <= paper;  'ge': computed >= paper;  'rel': |c/p-1| <= tol (tol given)
    tol      explicit tolerance (absolute, or relative for 'rel') and `why` (reason) when the rounding rule is not enough
A getter may also be a function f(text)->(float, token) for values that need a computation (differences, ratios, orders of convergence).
"""
import os, re, math

CHECKS = []
_cache = {}
_ROOT = '.'


def C(id, loc, paper, log, pat, grp=1, n=0, kind='eq', tol=None, why='', scale=1.0, quantity='', fn=None, mode='quick', fix=None):
    """fix=(old text, new text): the manuscript value is wrong; `paper` is the corrected value that the script reproduces and (old, new) is reported as a proposed manuscript change"""
    CHECKS.append(dict(id=id, loc=loc, paper=paper, log=log, pat=pat, grp=grp, n=n, kind=kind, tol=tol, why=why, scale=scale, quantity=quantity or id, fn=fn, mode=mode, fix=fix))


def CM(id, loc, papers, log, pat, n=0, **kw):
    """one check per capture group of `pat`; papers[i] is the manuscript value of group i+1 (None: group not quoted)"""
    for i, p in enumerate(papers):
        if p is not None:
            C('%s.%d' % (id, i + 1), loc, p, log, pat, grp=i + 1, n=n, **kw)


def ulp(s):
    """unit in the last digit of the decimal string s (handles 1.3e-7, 0.0489, 205)"""
    s = str(s).strip()
    m = re.match(r'[-+]?(\d*)\.?(\d*)(?:[eE]([-+]?\d+))?$', s)
    if not m:
        return 0.0
    frac = m.group(2) or ''
    ex = int(m.group(3)) if m.group(3) else 0
    return 10.0 ** (ex - len(frac))


def fmt(x):
    return '%.6g' % x


def evaluate(LOGS, ROOT, mode, recs, shipped=None):
    """shipped: {job id: path of the shipped log, relative to the repository} for jobs that are not part of this mode (long jobs in a quick run): their checks then read the shipped log"""
    global _ROOT
    _ROOT = ROOT
    shipped = shipped or {}
    out = []
    for c in CHECKS:
        if c['mode'] == 'full' and mode != 'full':
            continue
        rec = dict(id=c['id'], quantity=c['quantity'], loc=c['loc'], paper=c['paper'], tol='', reason=c['why'], computed='', status='', detail='')
        if c.get('fix'):
            rec['fix'] = list(c['fix'])
            rec['paper'] = '%s (manuscript: %s)' % (c['paper'], c['fix'][0])
        logs = c['log'].split('+')
        bad = None
        paths = {}
        for lg in logs:
            r = recs.get(lg)
            if r is None and lg in shipped and not recs.get('__only__'):   # long job in a quick run: the check reads the shipped log (regenerated by --full)
                sp = os.path.join(ROOT, shipped[lg])
                if os.path.exists(sp):
                    paths[lg] = sp
                    rec['detail'] = 'read from the shipped log (the generating job is part of --full)'
                    continue
            if r is None:                                   # the job is not part of this mode (quick/full) or of this --only selection
                bad = ('OMIT', '')
                break
            if r['status'] == 'SKIPPED' or not os.path.exists(os.path.join(LOGS, lg + '.log')):
                bad = ('SKIPPED', 'job %s did not run (%s)' % (lg, r['cmp_detail']))
                break
            if r['status'] == 'FAILED':
                bad = ('FAIL', 'job %s failed' % lg)
                break
        if bad:
            if bad[0] == 'OMIT':
                continue
            rec['status'], rec['detail'] = bad
            out.append(rec)
            continue
        texts = []
        for lg in logs:
            path = paths.get(lg) or os.path.join(LOGS, lg + '.log')
            t = _cache.get(path)
            if t is None:
                t = _cache[path] = open(path, errors='replace').read()
            texts.append(t)
        text = '\n'.join(texts)
        try:
            if c['fn'] is not None:
                val, tokulp = c['fn'](text)
            else:
                ms = list(re.finditer(c['pat'], text, re.M))
                if len(ms) <= c['n']:
                    raise ValueError('pattern matched %d times, need index %d' % (len(ms), c['n']))
                tok = ms[c['n']].group(c['grp'])
                val = float(tok) * c['scale']
                tokulp = ulp(tok) * abs(c['scale'])
            p = float(c['paper'])
            if c['kind'] == 'eq':
                tol = c['tol'] if c['tol'] is not None else 0.5 * ulp(c['paper']) + 0.5 * tokulp
                ok = abs(val - p) <= tol * (1 + 1e-9)
                rec['tol'] = '%s' % fmt(tol)
            elif c['kind'] == 'rel':
                tol = c['tol']
                ok = abs(val / p - 1) <= tol
                rec['tol'] = 'rel %s' % fmt(tol)
            elif c['kind'] == 'le':
                slack = c['tol'] if c['tol'] is not None else 1e-9 * abs(p)
                ok = val <= p + slack
                rec['tol'] = 'bound: <= paper' + (' (+%s: %s)' % (fmt(slack), c['why']) if c['tol'] is not None else '')
            elif c['kind'] == 'ge':
                slack = c['tol'] if c['tol'] is not None else 1e-9 * abs(p)
                ok = val >= p - slack
                rec['tol'] = 'bound: >= paper' + (' (-%s: %s)' % (fmt(slack), c['why']) if c['tol'] is not None else '')
            else:
                raise ValueError(c['kind'])
            rec['computed'] = fmt(val)
            rec['status'] = 'PASS' if ok else 'FAIL'
        except Exception as e:   # a pattern that does not match is a failure of the check
            rec['status'] = 'FAIL'
            rec['detail'] = 'could not evaluate: %s' % e
            rec['computed'] = 'n/a'
        out.append(rec)
    return out


# helpers for getters ---------------------------------------------------------------------------------------------------------------------
def nums(line):
    return [float(x) for x in re.findall(r'[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?', line)]


def lines_with(text, key):
    return [l for l in text.split('\n') if key in l]


