# --- (f) derivation from the reduced action: exact rational arithmetic -------------------------------------------------------------------------------
def _cnt(pattern, ctrl=False):
    def f(t):
        n = 0
        for l in t.split('\n'):
            if re.search(pattern, l) and (('CONTROL' in l) == ctrl):
                n += 1
        return float(n), 0.0
    return f


C('action_n_tests', S4 + '(f): number of tests with c = 4 pi/h, h of degree 4 and 6 (d_v C_u = 0 exactly)', '30', 'action_check', None, fn=_cnt(r'd_v C_u=0 \(exact\)'), tol=0.0, why='integer count of exact-zero tests')
C('action2_n_exact', S4 + '(f): tests with a_2 = 0, difference exactly zero (action_check2.py)', '12', 'action_check2', None, fn=_cnt(r'sigma_uv\(action\)-sigma_uv\(paper\)=0 \(exact\)'), tol=0.0, why='integer count')
C('action3_n_tests', S4 + '(f): tests with a_2 != 0 (action_check3.py)', '8', 'action_check3', None, fn=_cnt(r'sigma_uv\(action\)-sigma_uv\(paper\)='), tol=0.0, why='integer count')


def _maxabs(pattern, ctrl=False, fnc=max):
    def f(t):
        v = []
        for l in t.split('\n'):
            if (('CONTROL' in l) == ctrl):
                m = re.search(pattern, l)
                if m:
                    v.append(abs(float(m.group(1))))
        if not v:
            raise ValueError('no lines')
        return fnc(v), 0.0
    return f


C('action3_maxdiff', S4 + '(f): at most 1.3e-14 in the 8 tests with a_2 != 0', '1.3e-14', 'action_check3', None, kind='le', fn=_maxabs(r'sigma_uv\(action\)-sigma_uv\(paper\)=(\S+)'))
C('action_control_11', S4 + '(f): for a Raychaudhuri coefficient 1.1 times larger the difference is 6e-3 or more (the a_2 != 0 tests, action_check3.py; action_check2.py: 3.0e-3)', '6e-3', 'action_check3', None, kind='ge',
  fn=_maxabs(r'sigma_uv\(action\)-sigma_uv\(paper\)=(\S+)', True, min))
C('action_control_psi5', S4 + '(f): for c(1+psi/5) the difference is not zero (smallest value over the three logs; bound 1e-4)', '1e-4', 'action_check+action_check2+action_check3', None, kind='ge',
  fn=lambda t: (min(abs(float(m.group(1))) for l in t.split('\n') if 'CONTROL' in l and ('1/5' in l) for m in [re.search(r'sigma_uv\(action\)-sigma_uv\(paper\)=(\S+)', l)] if m), 0.0))
