C('action_c3_max', S4 + '(f): ... largest c3 term (action_check2.py, a_2 = 0, reaches 1.7)', '1e-1', 'action_check3', None, kind='le', fn=_maxabs(r'c3 term:? ?(\S+?)[;)]', False, max))
# --- (g) lift_check_4d ---------------------------------------------------------------------------------------------------------------------------------
def _lift(keys):
    def f(t):
        v = []
        for l in t.split('\n'):
            if any(l.startswith(k) for k in keys) and 'control' not in l:
                m = re.search(r'diff=(\S+)', l)
                if m:
                    v.append(float(m.group(1)))
        if not v:
            raise ValueError('no lines')
        return max(v), 0.0
    return f


C('lift_reduced', S4 + '(g)(i): reductions R, I_C2, I_C3, I_Rh2, I_Rh3, I_R2C agree to', '9e-11', 'lift_check_4d', None, kind='le', fn=_lift(['R ', 'IC2', 'IC3', 'IRh2', 'IRh3', 'IR2C']))
C('lift_lifts', S4 + '(g)(ii): lifts P, H, T, K reproduce psi, eta, tau, calR to', '3e-11', 'lift_check_4d', None, kind='le', fn=_lift(['H=eta', 'T=tau', 'P=psi', 'K=calR']))
C('lift_gr', S4 + '(g)(iii): density with H2 = 2P, H3 = 4, H4 = 1 equals the Ricci scalar to', '3e-13', 'lift_check_4d', None, kind='le', fn=_lift(['GR dens']))
C('lift_control', S4 + '(g): the control (the wrong fourth term) must fail: smallest control difference > 1', '1', 'lift_check_4d', None, kind='ge', fn=lambda t: (min(float(m.group(1)) for m in re.finditer(r'must fail\) .*diff=(\S+)', t)), 0.0))

