# Sections 7-9: data, validation against exact static data (t_static_*.log), free versus constrained evolution
# ======================================================================================================================================
S7 = 'Sec. 7 Event-horizon-regular data'
S8 = 'Sec. 8 Constrained evolution'
_TOK = r'[-+]?(?:\d+\.\d*|\.\d+|\d+)(?:[eE][-+]?\d+)?|[-+]?nan'


def _blockline(t, name, v):
    lines = t.split('\n')
    inb = False
    for l in lines:
        if re.match(r'^\w+$', l):
            inb = (l == name)
            continue
        if inb and l.strip().startswith('v=%d:' % v):
            return l
    raise ValueError('block %s v=%d not found' % (name, v))


def _sval(name, v, g, idx, nan=False):
    """error value from t_static_*.log: block name, row v=<v>, ray group g (0..3), mesh idx 0..3 or 4 = Richardson-Romberg"""
    def f(t):
        seg = _blockline(t, name, v).split(':', 1)[1].split('||')[g]
        toks = re.findall(_TOK, seg.replace('RR', ' '))
        tok = toks[idx]
        if nan:
            return (1.0 if 'nan' in tok else 0.0), 0.0
        if 'nan' in tok:
            raise ValueError('non-finite value')
        return abs(float(tok)), ulp(tok.lstrip('+-'))
    return f


def _maxRR(names=('r', 'sigma_v', 'psi')):
    def f(t):
        m = 0.0
        for nme in names:
            for v in (40, 60, 80, 98):
                for seg in _blockline(t, nme, v).split(':', 1)[1].split('||'):
                    toks = re.findall(_TOK, seg.replace('RR', ' '))
                    if 'nan' not in toks[4]:
                        m = max(m, abs(float(toks[4])))
        return m, 0.0
    return f


