# ======================================================================================================================================
# Section 9: results for the Hayward characteristic function (data/genq_*.json, four meshes)
# ======================================================================================================================================
S9 = 'Sec. 9 Hayward'


def _sig(tok):
    return float(tok), ulp(tok.lstrip('+-'))


def ROW(block_re, v, idx, key=None):
    """number idx (0-based, parentheses ignored) of the row whose first number is v, in the block that starts at the first line matching block_re (ends at the next line starting with '---')"""
    def f(t):
        lines = t.split('\n')
        start = None
        for i, l in enumerate(lines):
            if re.search(block_re, l):
                start = i
                break
        if start is None:
            raise ValueError('block %r not found' % block_re)
        for l in lines[start + 1:]:
            if l.startswith('---') or l.startswith('==='):
                break
            toks = re.findall(_TOK, l.replace('(', ' ').replace(')', ' '))
            if toks and float(toks[0]) == v:
                return _sig(toks[idx])
        raise ValueError('row v=%g not found' % v)
    return f


def LINE(pat, idx=0, n=0):
    """number idx of the n-th line matching pat (all numbers of the line, after the match start)"""
    def f(t):
        ms = [l for l in t.split('\n') if re.search(pat, l)]
        toks = re.findall(_TOK, ms[n].replace('(', ' ').replace(')', ' '))
        return _sig(toks[idx])
    return f


