def _offdiff(t):
    a = []
    for blk in t.split('B=')[1:]:
        a.append({int(l.split()[0]): float(l.split()[3]) for l in blk.split('\n') if re.match(r'^\s+\d+\s+-?\d', l)})
    return max(abs(a[0][v] - a[1][v]) for v in a[0] if v >= 60), 0.0


