# --- Table tab:k (ktable.log) ---------------------------------------------------------------------------------------------------------------------
def KT(v, case, part):
    """ktable.log: row v, case 0..4 (k=1/2; k=3/2 B=3e-4, 3e-3, 3e-2; k=3), part 0 = sigma_v, 2 = difference from G (units 1e-4)"""
    def f(t):
        for l in t.split('\n'):
            tk = l.split()
            if tk and tk[0] == str(v):
                pos = 1
                for cs in range(5):
                    if pos >= len(tk):
                        raise ValueError('row too short')
                    if tk[pos] == '--':
                        if cs == case:
                            raise ValueError('entry is --')
                        pos += 1
                        continue
                    if cs == case:
                        tok = tk[pos + part]
                        sc = 1e4 if part == 2 else 1.0
                        return float(tok) * sc, ulp(tok.lstrip('+-')) * sc
                    pos += 3
        raise ValueError('row %s not found' % v)
    return f


def KTdash(v, case):
    def f(t):
        for l in t.split('\n'):
            tk = l.split()
            if tk and tk[0] == str(v):
                pos = 1
                for cs in range(5):
                    if pos >= len(tk):
                        return 1.0, 0.0                        # row ends: entries beyond are absent
                    if tk[pos] == '--':
                        if cs == case:
                            return 1.0, 0.0
                        pos += 1
                    else:
                        if cs == case:
                            return 0.0, 0.0
                        pos += 3
                return 1.0, 0.0
        raise ValueError('row not found')
    return f


