# --- slaving (Sec. 9, "Behind the front the solution is slaved to the interior flux") ---------------------------------------------------------------
def SPROWS(t, v):
    """rows (x, rho, phi_v, sigma_v, S/rho, rho_v/rho, z) of the block 'v=<v>' of slaving_prof.log"""
    rows, inb = [], False
    for l in t.split('\n'):
        if l.startswith('v='):
            inb = (int(l.split()[0][2:]) == v)
            continue
        if inb:
            tk = re.findall(_TOK, l)
            if len(tk) == 7 and not l.strip().startswith('x'):
                rows.append([float(x) for x in tk])
    if not rows:
        raise ValueError('block v=%d not found' % v)
    return rows


