def _rho_var(v, xmin):
    def f(t):
        r = [x for x in SPROWS(t, v) if x[0] >= xmin]
        rho = [x[1] for x in r]
        return (max(rho) - min(rho)) / (sum(rho) / len(rho)), 0.0
    return f


