def _combo(v, xlo, xhi):
    def f(t):
        r = [x[5] for x in SPROWS(t, v) if xlo <= x[0] <= xhi]
        return (max(r) + min(r)) / 2, 0.0
    return f


def _combo_half(v, xlo, xhi):
    def f(t):
        r = [x[5] for x in SPROWS(t, v) if xlo <= x[0] <= xhi]
        return (max(r) - min(r)) / 2, 0.0
    return f


