def _vG(v):
    def f(t):
        for l in t.split('\n'):
            tk = l.split()
            if tk and tk[0] == str(v):
                return float(tk[-2]), ulp(tk[-2].lstrip('+-'))
        raise ValueError('row %d not found' % v)
    return f


