def VBL(B, h, idx):
    def f(t):
        blk = t.split('B=' + B + '\n')[1].split('\ngenq2')[0]
        m = re.search(r'h_v=%s +first non-finite sample: (.*?) +law: (\S+)' % re.escape(h), blk)
        return float(m.group(idx)), 1.0 if idx == 1 else 0.1
    return f


