CB_ = 'Sec. 7 Code B'


def _b4(name, v, i):
    """errors of block `name` at v for mesh i (0..3), t_static_b4.log"""
    def f(t):
        blk = t.split('\n%s (errors' % name)[1].split('\n')
        for l in blk[1:]:
            if l.strip().startswith('v=%d:' % v):
                toks = re.findall(_TOK, l.split(':', 1)[1])
                return float(toks[i]), ulp(toks[i])
        raise ValueError('not found')
    return f


