# (ii) cmp_hs  (columns: |0.05-0.025| ; |0.05-0.0125| ; |0.025-0.0125| ; ratio)
def _hs(name, v, col):
    def f(t):
        l = [l for l in t.split('\n') if l.startswith(name + ' ')][0]
        m = re.search(r'\b%d: (\S+);(\S+);(\S+);(\S+)' % v, l)
        return float(m.group(col)), ulp(m.group(col))
    return f


