ME_ = 'Sec. 8 Mechanism'


def _mv(p, hv, col, ratio=False):
    """mech_vb log: order p block, row hv, error column col (0..3 = v=100,150,200,250) or ratio (col 0..3)"""
    def f(t):
        blk = t.split('--- order p=%d' % p)[1].split('---')[0]
        for l in blk.split('\n'):
            if l.startswith('hv=%s ' % hv):
                if ratio:
                    return float(l.split('ratio')[1].split()[col]), 0.05
                tok = l.split('ratio')[0].split()[1 + col]
                return float(tok), ulp(tok)
        raise ValueError('no row')
    return f


