def _vp(B, hv, what):
    def f(t):
        blk = re.split(r'B=%s\s+predicted' % re.escape(B), t)[1].split('\nB=')[0]
        m = re.search(r'hv=%s\s+predicted\s+(\S+)\s+measured\s+(\S+)' % re.escape(hv), blk)
        s = m.group(1 if what == 'pred' else 2)
        return float(s) if s != '-' else float('nan'), ulp(s) if s != '-' else 0.0
    return f


