CE_ = 'Sec. 8 Code E'


def _te(name, v, i):
    def f(t):
        blk = t.split('\n%s (errors' % name)[1].split('\n')
        for l in blk[1:]:
            if l.strip().startswith('v=%d:' % v):
                toks = re.findall(r'\d\.\d+e[-+]\d+', l)
                return float(toks[i]), ulp(toks[i])
        raise ValueError
    return f


