def _ce2(row, key, v):
    def f(t):
        l = [l for l in t.split('\n') if l.startswith(row)][0]
        m = re.search(r'v=%d: dK/K=(\S+) dr/r=(\S+) dsv=(\S+)' % v, l)
        s = m.group({'dK': 1, 'dr': 2, 'dsv': 3}[key])
        return float(s), ulp(s)
    return f


