def _cev(v, key):
    def f(t):
        l = [l for l in t.split('\n') if l.startswith('v=%d ' % v)][0]
        m = re.search(r'%s: E=(\S+) B=(\S+) rel.diff=(\S+)' % key, l)
        return float(m.group(3)), ulp(m.group(3))
    return f


