CO_ = 'Sec. 12 Collapse'


def _int(u0, col):
    """interior.log: row with u= u0, field col in ('r','psi','static','rel','rv')"""
    def f(t):
        for l in t.split('\n'):
            m = re.match(r'u=\s*(\S+) r=\s*(\S+) psi=(\S+) static=(\S+) rel=(\S+) rv=(\S+)', l)
            if m and abs(float(m.group(1)) - u0) < 1e-6:
                s = m.group({'r': 2, 'psi': 3, 'static': 4, 'rel': 5, 'rv': 6}[col])
                return float(s), ulp(s)
        raise ValueError
    return f


