def _fit(mo, win, what):
    def f(t):
        blk = t.split('model %d A=' % mo)[1].split('model')[0]
        m = re.search(r't in \[%s\]: free k=(\S+) \(B=(\S+), vs-vstart=(\S+)\) \| k=3: B=(\S+) vs-vstart=(\S+)' % win, blk)
        s = m.group({'k': 1, 'Bfree': 2, 'vsfree': 3, 'B3': 4, 'vs3': 5}[what])
        return float(s), ulp(s)
    return f


