def TB(key, col, nfield=None):
    """whitespace field number col (0-based, after the key) of the first line that starts with `key` (table rows keyed by a file name or run name); tokens like '-0.0464' or '1.0059' are returned with their ulp"""
    def f(t):
        for l in t.split('\n'):
            p = l.split()
            if p and p[0] == key:
                tok = p[1 + col]
                return float(tok), ulp(tok.lstrip('+-'))
        raise ValueError('row %s not found' % key)
    return f


def TBabs(key, col):
    return lambda t: (abs(TB(key, col)(t)[0]), TB(key, col)(t)[1])


# ---- collapse_E.log -----------------------------------------------------------------------------------------------------------------
def _ce(fn, ray, V, what):
    def f(t):
        for l in t.split('\n'):
            if l.startswith(fn) and (' ray %d ' % ray) in l and ('v=%d:' % V) in l:
                m = re.search(what + r'=(\S+)', l)
                return float(m.group(1)), ulp(m.group(1))
        raise ValueError
    return f


def _cfront(fn, ray):
    def f(t):
        for l in t.split('\n'):
            if l.startswith(fn) and (' ray %d ' % ray) in l:
                return float(re.search(r'front v=\s*(\d+)', l).group(1)), 0.0
        raise ValueError
    return f


