# k = 2 tail, collapse_E_k2.log and k2_extra.log


def K2(fi, ray, V, col):
    """collapse_E_k2.log: block 'ce/genc_<fi>_hs0.2_hv0.2_v1500.json ray <ray> U=...', row with v=V, column col (0 v, 1 zm, 2 dm/dv, 3 v0, 4 v*sV, 5 slope, 6 formula, 7 slope+terms)"""
    def f(t):
        blocks = re.split(r'(?=^ce/genc)', t, flags=re.M)
        for b in blocks:
            if b.startswith('ce/genc_%s_hs0.2_hv0.2_v1500.json ray %d ' % (fi, ray)):
                for r in b.split('\n'):
                    p = r.split()
                    if len(p) == 8 and p[0] == str(V):
                        return float(p[col]), ulp(p[col].lstrip('-'))
        raise ValueError('k2 row %s %d %d' % (fi, ray, V))
    return f


