# ---- k = 2: np_fit.log, nplin.log, np_lin_b.log, overlap_np.log, tc_fit.log -----------------------------------------------------------------------
def FIT(head, lo, kind, idx=0):
    """a0 of the window [lo,...] (kind 'a0', form idx 0..2) or the free fit (kind 'k' or 'B' or 's') for the block whose header line starts with `head`"""
    def f(t):
        t = re.sub(r'(?m)^\S*Warning.*\n\s.*\n', '', t) if False else '\n'.join(l for l in t.split('\n') if not re.search(r'Warning:|^\s+r=lambda|^\s+f=lambda', l))
        blk = [b for b in re.split(r'(?m)^(?=\S)', t) if b.startswith(head)][0]
        if kind == 'a0':
            m = re.search(r'window \[%d,\d+\]: a0 = (\S+)\s+(\S+)\s+(\S+)' % lo, blk)
            s = m.group(1 + idx)
            return float(s), ulp(s)
        m = re.search(r'free \(B,s,k\) window \[%d,\d+\]: B/\(4\|(?:b|I0)\|\)=(\S+)\s+s=(\S+)\s+k=(\S+)' % lo, blk)
        s = m.group({'B': 1, 's': 2, 'k': 3}[kind])
        return float(s), ulp(s.lstrip('-'))
    return f


