# ---- ascale_q.log: B/(8m|Q|) for A/A0 = 0.8 ... 1.2 and the charge of the exterior part of the row v = 60 (ascale_q.py, new generator built from the original functions)
def _aq(sec, a, col):
    def f(t):
        part = t.split('(2)')[sec - 1]
        for l in part.split('\n'):
            p = l.split()
            if p and p[0] == a:
                return float(p[col]), ulp(p[col].lstrip('+-'))
        raise ValueError('row %s not found' % a)
    return f


