QA_ = 'Table tab:qabs'


def _mean(x):
    x = list(x)
    return sum(x) / len(x)


def _pstd(x):
    x = list(x)
    m = sum(x) / len(x)
    return (sum((v - m) ** 2 for v in x) / len(x)) ** 0.5



def HR(key, what):
    """horizon_ray.log: row `key`; what = 'Qabs' (from the bracket) or a column number"""
    def f(t):
        for l in t.split('\n'):
            p = l.split()
            if p and p[0] == key:
                if what == 'Qabs':
                    m = re.search(r'Qabs=(\S+)', l)
                    return abs(float(m.group(1))), ulp(m.group(1).lstrip('-'))
                tok = p[1 + what]
                return abs(float(tok)), ulp(tok.lstrip('+-'))
        raise ValueError(key)
    return f


def HRall(col):
    """list of float values of column col over the valid rows of horizon_ray.log (22 cases)"""
    def f(t):
        out = []
        for l in t.split('\n'):
            p = l.split()
            if len(p) > 11 and p[0].endswith('.npz') and re.match(r'^-?\d', p[3]):
                out.append(float(p[1 + col]) if col != 'Qabs' else abs(float(re.search(r'Qabs=(\S+)', l).group(1))))
        return out
    return f


