# ---- Table tab:pscan and the pulse-strength scan (scan_summary, scan_zm, scan_an, horizon_map, vaidya_estimate, conv_P*) ------------------
PS_ = 'Table tab:pscan'


def SSM(P, pat):
    def f(t):
        for l in t.split('\n'):
            if l.startswith('P=%s ' % P):
                m = re.search(pat, l)
                return float(m.group(1)), ulp(m.group(1).lstrip('-'))
        raise ValueError(P)
    return f


