def AN(P, v, col):
    def f(t):
        for l in t.split('\n'):
            p = l.split()
            if len(p) == 5 and p[0].startswith('genc_P%s_hs0.2' % P) and p[1] == str(v):
                return float(p[col]), ulp(p[col].lstrip('-'))
        raise ValueError((P, v))
    return f


