# horizon map / fold
def HM(P, rf):
    def f(t):
        for l in t.split('\n'):
            if l.startswith('P=%s ' % P):
                m = re.search(r' %s:(\S+)' % rf, l)
                return float(m.group(1)), ulp(m.group(1))
        raise ValueError
    return f


