def _rp(m, ell=1.0):
    """outer root of r^3 - 2 m r^2 + 2 m l^2 = 0 (Hayward, l=1): bisection"""
    f = lambda r: r ** 3 - 2 * m * r ** 2 + 2 * m * ell ** 2
    lo, hi = 2 * m * 0.9, 2 * m * 1.01
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if f(mid) > 0:
            hi = mid
        else:
            lo = mid
    return 0.5 * (lo + hi)


