# ---- mesh dependence of the scan (conv_P0.08_hv, conv_P0.07_hs) ---------------------------------------------------------------------------------
def RXN(pat, n=-1):
    """group 1 of the n-th (default last) line match of pat (re.M) as a number with its ulp"""
    def f(t):
        m = re.findall(pat, t, re.M)
        tok = m[n]
        return float(tok), ulp(tok.lstrip('-'))
    return f


def CV(v, col):
    def f(t):
        for l in t.split('\n'):
            p = l.split()
            if len(p) == 5 and p[0] == 'v=' and p[1] == str(v):
                return float(p[1 + col]), ulp(p[1 + col])
        raise ValueError(v)
    return f


def _cvmax(col, vs):
    return lambda t: (max(CV(v, col)(t)[0] for v in vs), 0.0)


# the lines read 'v= 100  2.22e-02 ...': tokens are 'v=', '100', ... -> use own splitter
def CV(v, col):  # noqa: F811
    def f(t):
        for l in t.split('\n'):
            m = re.match(r'^v=\s*(\d+)\s+(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s*$', l)
            if m and int(m.group(1)) == v:
                tok = m.group(2 + col)
                return float(tok), ulp(tok)
        raise ValueError(v)
    return f


