# ---- a priori estimates of Q_abs (eik_test.log, eik_summary.log, eik2.log) ---------------------------------------------------------------------
EK_ = 'Sec. 12 strong, a priori estimate of Q_abs'


def _eik_pairs(t):
    """[(table name, max|psi_H|/max|psi_in|)] from eik_test.log: the eikonal line precedes the table row it belongs to"""
    out, cur = [], None
    for l in t.split('\n'):
        m = re.search(r'max\|psi_in\|=(\S+) max\|psi_H\|=(\S+)', l)
        if m:
            cur = float(m.group(2)) / float(m.group(1))
        elif cur is not None and l.split() and l.split()[0].endswith('.npz'):
            out.append((l.split()[0], cur))
            cur = None
    return out


