# eik2: linear transfer
def E2(key, col):
    def f(t):
        for l in t.split('\n'):
            p = l.split()
            if p and p[0] == key:
                return float(p[col]), 0.0
        raise ValueError(key)
    return f


def E2pct(key, col):
    return lambda t: (100 * (E2(key, col)(t)[0] / E2(key, 3)(t)[0] - 1), 0.0)


