# ---- BCR flat-space benchmark (tailfit_results.log, s2a_results.log, convergence_h.log) -----------------------------------------------------
BC_ = 'Sec. 12 BCR benchmark'


def TF(block, r, what):
    """tailfit_results.log: block 0 = symmetric pulse, 1 = asymmetric (a -> a[1+1.5(x-1/2)]); r = 5, 10, 20; what: c3, c2, t100, t300, X1, X2, X4, M, ratio1 (c/X1 of 3par)"""
    def f(t):
        parts = re.split(r'(?m)^(?=Madm)', t)
        parts = [p for p in parts if p.startswith('Madm')]
        p = parts[block]
        if what in ('X1', 'X2', 'X4', 'M'):
            m = re.match(r'Madm (\S+) Q (\S+) \| X1=-8 int M_B a (\S+)  X4=-8 int M_in a (\S+)  X2=-8 M Q (\S+)', p)
            tok = {'M': m.group(1), 'X1': m.group(3), 'X4': m.group(4), 'X2': m.group(5)}[what]
            return float(tok), ulp(tok.lstrip('-'))
        for l in p.split('\n'):
            m = re.match(r'r=%d\s+t\^3D\(t=100,150,200,300\)=\s*(\S+)\s+(\S+)\s+(\S+)\s+(\S+)\s+fit\(3par\) c=(\S+)\s+fit\(2par\) c=(\S+)\s+c/X1=(\S+)\s+c/X2=(\S+)' % r, l)
            if m:
                g = {'t100': 1, 't300': 4, 'c3': 5, 'c2': 6, 'r1': 7, 'r2': 8}[what]
                tok = m.group(g)
                return float(tok), ulp(tok.lstrip('-'))
        raise ValueError((block, r, what))
    return f


