# s2a
def S2(eps, col):
    def f(t):
        for l in t.split('\n'):
            m = re.match(r'^(0\.\d\d) (\S+) \|\s+(\S+)\s+(\S+)\s+(\S+) \|\s+(\S+)\s+(\S+)\s+(\S+) \| (\S+) \|\s+(\S+) \|\s+(\S+)\s*$', l)
            if m and m.group(1) == eps:
                tok = m.group(col)
                return float(tok), ulp(tok.lstrip('-'))
        raise ValueError(eps)
    return f


