def _kappa_plus(m):
    """surface gravity of the Hayward hole, ell=1: f = 1 - 2 m r^2/(r^3+2m), kappa = f'(r_+)/2"""
    rp = _rp(m)
    f1 = -(2 * m * (2 * rp * (rp ** 3 + 2 * m) - rp ** 2 * 3 * rp ** 2)) / (rp ** 3 + 2 * m) ** 2
    return f1 / 2


# ---- near-extremal horizon field (nearext.py; not quoted in main.tex): the quick run to t=1600 reproduces the entries t<=800 of the original runs ----
def _near_entries(text):
    out = []
    for l in text.split('\n'):
        m = re.match(r'^m=(\S+) kappa\+=(\S+) Lh=(\d+) \| (.*)$', l)
        if m:
            d = {}
            for T, a, b in re.findall(r'(\d+): t2phi=(\S+) t3phi=(\S+)', m.group(4)):
                d[int(T)] = (float(a), float(b))
            out.append((m.group(1), int(m.group(3)), d))
    return out


def _near_cmp(t):
    ship = []
    for nm in ('nearext.log', 'nearext2.log'):
        with open(os.path.join(_ROOT, 'code/eh_qtg/codec/sp', nm)) as fh:
            ship += _near_entries(fh.read())
    new = _near_entries(t)
    assert len(new) == len(ship), (len(new), len(ship))
    worst = 0.0
    for (m1, L1, d1), (m2, L2, d2) in zip(new, ship):
        assert m1 == m2 and abs(L1 - L2) <= 1, (m1, m2, L1, L2)
        scale = max(abs(a) for a, b in d2.values() if True)
        for T in (200, 400, 800):
            worst = max(worst, abs(d1[T][0] - d2[T][0]) / max(abs(d2[T][0]), 0.02 * scale, 1e-3))
    return worst


C('nearext_repro', 'nearext.py (not quoted in main.tex): the quick run (t<=1600, h=0.25) reproduces t^2 phi_H at t = 200, 400, 800 of the original runs (sp/nearext.log, sp/nearext2.log, to t = 25600), largest relative difference', '0.02', 'nearext', None, kind='le', tol=0.0,
  why='printed with 3 digits; the transient at t=100 depends on the mesh of the original runs (up to 4%), so t = 100 is not compared', fn=lambda t: (_near_cmp(t), 0.0))


# ---- Appendix A: the ray tests (ray_blowup.log, scan_u_h0.0025.log, pde_blowup_h0.02.log, model2_h0.02.log, conv_B2e-4.log, check_psi_identity.log) --------
AP_ = 'App. A (ray tests)'


def RB(B, what):
    def f(t):
        for l in t.split('\n'):
            m = re.match(r'^\s+B=(\S+)\s+v_\*=\s*(\S+)\s+psi\(v_\*\)=(\S+)\s+r-r_-=(\S+)\s+status', l)
            if m and float(m.group(1)) == float(B):
                tok = {'v': m.group(2), 'psi': m.group(3), 'dr': m.group(4)}[what]
                return float(tok), ulp(tok.lstrip('+-'))
        raise ValueError(B)
    return f


