# classification of rays
def SU(u, v, what):
    def f(t):
        for l in t.split('\n'):
            m = re.match(r'^ u=\s*(-?\d+)\s+(.*)$', l)
            if m and int(m.group(1)) == u:
                mm = re.search(r'v=%d:psi (\S+) y (\S+) sv (\S+)' % v, m.group(2))
                tok = {'psi': mm.group(1), 'y': mm.group(2), 'sv': mm.group(3)}[what]
                return float(tok), ulp(tok.lstrip('+-')) if what != 'y' else 0.0
        raise ValueError((u, v))
    return f


