def _rminus(m):
    """inner root of r^3 - 2 m r^2 + 2 m (l=1)"""
    f = lambda r: r ** 3 - 2 * m * r ** 2 + 2 * m
    lo, hi = 0.5, 2.0
    # smallest positive root: f(0)=2m>0, f decreasing near 0 until the root
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if f(mid) > 0:
            lo = mid
        else:
            hi = mid
    return 0.5 * (lo + hi)


