# resolution study
def CVT(h, v, what='psi'):
    def f(t):
        for l in t.split('\n'):
            if l.startswith('h=%s ' % h):
                m = re.search(r'v=%d: psi (\S+) sv ([^;\s]+)' % v, l)
                tok = m.group(1 if what == 'psi' else 2)
                return float(tok), ulp(tok.lstrip('+-'))
        raise ValueError((h, v))
    return f


