# psi identity
def PI(h, win):
    def f(t):
        for l in t.split('\n'):
            if l.startswith('h=%-8s' % h) or l.split()[:1] == ['h=' + h]:
                toks = l.split()[-3:]
                return float(toks[win]), ulp(toks[win])
        raise ValueError(h)
    return f


