MC_ = 'Sec. 4 (checks) item (v), two discretizations (modecmp.log)'


def MCR(v, col):
    def f(t):
        for l in t.split('\n'):
            p = l.split()
            if len(p) == 8 and p[0] == str(v) and re.match(r'^-?\d', p[1]):
                return float(p[col]), ulp(p[col].lstrip('+-'))
        raise ValueError(v)
    return f


