C3_ = 'Sec. 4 (checks) item (vi), sensitivity to c_3 (c3_sensitivity.log)'


def C3(v, fac):
    def f(t):
        for l in t.split('\n'):
            p = l.split()
            if len(p) == 13 and p[0] == str(v):
                # columns: v, then (dsV, dz/z, sV(m3)) for FAC=1, 0, 1.1, 0.9
                k = {'1': 1, '0': 4, '1.1': 7, '0.9': 10}[fac]
                return float(p[k + 2]), ulp(p[k + 2].lstrip('-'))
        raise ValueError((v, fac))
    return f


def C3dz(v, fac):
    def f(t):
        for l in t.split('\n'):
            p = l.split()
            if len(p) == 13 and p[0] == str(v):
                k = {'1': 1, '0': 4, '1.1': 7, '0.9': 10}[fac]
                return float(p[k + 1]), 0.0
        raise ValueError((v, fac))
    return f


