# ---- figures: every figure of the manuscript is regenerated (verification/figures/); the check is the pixel size of the PNG ------------------
for _f, _lab in (('fig_qtg', 'Fig. qtg (App. A)'), ('fig_eh', 'Fig. eh (Sec. 9-10)'), ('fig_collapse', 'Fig. collapse (Sec. 13)'),
                 ('fig_collapse_k2', 'Fig. k2 (Sec. 13)'), ('fig_strong', 'Fig. strong (Sec. 14)')):
    C(_f + '_regenerated', _lab + ': figure regenerated from the shipped data/logs; same pixel dimensions as the figure in the paper (image content depends on the matplotlib version)',
      '1', _f, None, fn=_cnt(r'dimensions identical$'), tol=0.0, why='count of the dimension comparison line (1 = identical size)')
C('fig_qtg_slope', 'Fig. qtg a / App. A: slope of the linear fit of v_* against log10(1/B) for B <= 2e-2: 12.3 per decade', '12.3', 'fig_qtg', r'slope per decade ([-\d.]+)', tol=0.05, why='12.3 rounded (fit of make_figs.py)')
C('fig_qtg_model2_finite', 'Fig. qtg c: the bounded-h run is finite everywhere (printed flag)', '1', 'fig_qtg', None, fn=_cnt(r'finite True'), tol=0.0, why='flag of make_figs.py')
